examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true })
if (open) {
    MonarchBottomSheet(
        onDismissRequest = { open = false },
        title = {{title}},
        description = {{description}},
    ) {
        MonarchText(text = {{body}})
        Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            MonarchButton(text = {{cancel}}, onClick = { open = false })
            MonarchButton(text = {{confirm}}, onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        }
    }
}

