if (open) {
    MonarchBottomSheet(
        onDismissRequest = { open = false },
        title = "Share link",
        description = "Anyone with the link can view this page.",
    ) {
        MonarchText(text = "Drag the handle down, press Escape or use Close to dismiss.")
        Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            MonarchButton(text = "Cancel", onClick = { open = false })
            MonarchButton(text = "Copy link", onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        }
    }
}
